-- FND-04 + RLS of profiles.
begin;
select plan(8);

insert into auth.users (id, email) values
  ('00000000-0000-0000-0000-00000000000a', 'a@test.local'),
  ('00000000-0000-0000-0000-00000000000b', 'b@test.local');

select is(
  (select count(*)::int from public.profiles where id in ('00000000-0000-0000-0000-00000000000a', '00000000-0000-0000-0000-00000000000b')),
  2, 'signup creates one profile per user');

select matches(
  (select username::text from public.profiles where id = '00000000-0000-0000-0000-00000000000a'),
  '^user_[a-z0-9]{8}$', 'username is autogenerated as user_ + 8 chars');

select isnt(
  (select username from public.profiles where id = '00000000-0000-0000-0000-00000000000a'),
  (select username from public.profiles where id = '00000000-0000-0000-0000-00000000000b'),
  'autogenerated usernames are distinct');

select ok(
  (select relrowsecurity from pg_class where oid = 'public.profiles'::regclass),
  'RLS is enabled on profiles');

update public.profiles set username = 'taken_name' where id = '00000000-0000-0000-0000-00000000000a';

-- act as user B
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"00000000-0000-0000-0000-00000000000b","role":"authenticated"}', true);

select is(
  (select count(*)::int from public.profiles where id = '00000000-0000-0000-0000-00000000000a'),
  0, 'other users cannot see a private profile');

update public.profiles set bio = 'hacked' where id = '00000000-0000-0000-0000-00000000000a';

select throws_ok(
  $$ update public.profiles set username = 'taken_name' where id = '00000000-0000-0000-0000-00000000000b' $$,
  '23505', null, 'username must be unique (owner editing to a taken name fails)');

reset role;
select is(
  (select bio from public.profiles where id = '00000000-0000-0000-0000-00000000000a'),
  null, 'other users cannot update a profile');

update public.profiles set is_public = true where id = '00000000-0000-0000-0000-00000000000a';
set local role authenticated;
select is(
  (select count(*)::int from public.profiles where id = '00000000-0000-0000-0000-00000000000a'),
  1, 'anyone authenticated can see a public profile');

select * from finish();
rollback;
